import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { InputValue, ItemSchema, Schema, WriteMode } from '~/schema/index.js'
import { cloneDeep } from '~/utils/cloneDeep.js'
import { isFunction } from '~/utils/validation/isFunction.js'

import { anySchemaParser } from './any.js'
import { anyOfSchemaParser } from './anyOf.js'
import { listSchemaParser } from './list.js'
import { mapSchemaParser } from './map.js'
import type { InferWriteValueOptions, ParseAttrValueOptions } from './options.js'
import type { ParserReturn, ParserYield } from './parser.js'
import { primitiveSchemaParser } from './primitive.js'
import { recordSchemaParser } from './record.js'
import { setSchemaParser } from './set.js'
import { defaultParseExtension, isRequired } from './utils.js'

export function* schemaParser<OPTIONS extends ParseAttrValueOptions = {}>(
  schema: Schema,
  inputValue: unknown,
  options: OPTIONS = {} as OPTIONS
): Generator<
  ParserYield<Schema, OPTIONS>,
  ParserReturn<Schema, OPTIONS>,
  // TODO: Define & use DefaultedValue here
  InputValue<ItemSchema, InferWriteValueOptions<OPTIONS, true>> | undefined
> {
  const {
    mode = 'put',
    fill = true,
    transform = true,
    defined = false,
    /**
     * @debt type "Maybe there's a way not to have to cast here"
     */
    parseExtension = defaultParseExtension as unknown as NonNullable<OPTIONS['parseExtension']>,
    valuePath
  } = options

  let filledValue = inputValue
  let nextFill = fill

  if (nextFill && filledValue === undefined) {
    let defaultedValue = undefined

    const modeDefault = getDefaulter(schema, mode)
    defaultedValue = isFunction(modeDefault) ? modeDefault() : (cloneDeep(modeDefault) as any)

    const itemInput = yield defaultedValue

    let linkedValue = defaultedValue
    if (linkedValue === undefined && itemInput !== undefined) {
      const modeLink = getModeLink(schema, mode)
      linkedValue = (isFunction(modeLink) ? modeLink(itemInput) : linkedValue) as any
    }
    yield linkedValue

    filledValue = linkedValue
    nextFill = false
  }

  const nextOpts = { ...options, fill: nextFill } as OPTIONS

  const { isExtension, extensionParser, unextendedInput } = parseExtension(schema, filledValue, {
    transform,
    valuePath
  })

  if (isExtension) {
    if (nextFill) {
      // parseExtension does not fill values
      // If fill was set to `true` and input was defined, we yield it twice for fill steps
      const defaultedValue = filledValue
      yield defaultedValue

      const linkedValue = defaultedValue
      yield linkedValue
    }
    return yield* extensionParser()
  }

  if (unextendedInput === undefined) {
    const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

    // We don't need to fill
    if (isRequired(schema, mode) || defined) {
      throw new DynamoDBToolboxError('parsing.attributeRequired', {
        message: `Attribute${path !== undefined ? ` '${path}'` : ''} is required.`,
        path
      })
    }

    const parsedValue = unextendedInput

    if (transform) {
      yield parsedValue
    } else {
      return parsedValue
    }

    const transformedValue = parsedValue
    return transformedValue
  }

  switch (schema.type) {
    case 'any':
      return yield* anySchemaParser(schema, unextendedInput, nextOpts)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return yield* primitiveSchemaParser(schema, unextendedInput, nextOpts)
    case 'set':
      return yield* setSchemaParser(schema, unextendedInput, nextOpts)
    case 'list':
      return yield* listSchemaParser(schema, unextendedInput, nextOpts)
    case 'map':
      return yield* mapSchemaParser(schema, unextendedInput, nextOpts)
    case 'record':
      return yield* recordSchemaParser(schema, unextendedInput, nextOpts)
    case 'anyOf':
      return yield* anyOfSchemaParser(schema, unextendedInput, nextOpts)
  }
}

const getDefaulter = (schema: Schema, mode: WriteMode) => {
  const { props } = schema

  if (props.key) {
    return props.keyDefault
  }

  switch (mode) {
    case 'key':
      return props.keyDefault
    case 'put':
      return props.putDefault
    case 'update':
      return props.updateDefault
  }
}

const getModeLink = (schema: Schema, mode: WriteMode) => {
  const { props } = schema

  if (props.key) {
    return props.keyLink
  }

  switch (mode) {
    case 'key':
      return props.keyLink
    case 'put':
      return props.putLink
    case 'update':
      return props.updateLink
  }
}

import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type { ExtensionParser, Schema, SchemaUnextendedValue, WriteMode } from '~/schema/index.js'
import { isString } from '~/utils/validation/isString.js'

import type { ParseAttrValueOptions } from './options.js'

export const defaultParseExtension: ExtensionParser<never> = (_, input) => ({
  isExtension: false,
  unextendedInput: input as SchemaUnextendedValue<never> | undefined
})

export const isRequired = (schema: Schema, mode: WriteMode): boolean => {
  switch (mode) {
    case 'put':
      return schema.props?.required !== 'never'
    case 'key':
    case 'update':
      return schema.props?.required === 'always'
  }
}

const getValidator = (schema: Schema, mode: WriteMode) => {
  if (schema.props.key) {
    return schema.props.keyValidator
  }

  switch (mode) {
    case 'key':
      return schema.props.keyValidator
    case 'put':
      return schema.props.putValidator
    case 'update':
      return schema.props.updateValidator
  }
}

export const applyCustomValidation = (
  schema: Schema,
  inputValue: unknown,
  options: ParseAttrValueOptions = {}
): void => {
  const { mode = 'put', valuePath } = options

  const customValidator = getValidator(schema, mode)
  if (customValidator !== undefined) {
    const validationResult = customValidator(inputValue, schema)

    if (validationResult !== true) {
      const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

      throw new DynamoDBToolboxError('parsing.customValidationFailed', {
        message: `Custom validation${
          path !== undefined ? ` for attribute '${path}'` : ''
        } failed${isString(validationResult) ? ` with message: ${validationResult}` : ''}.`,
        path,
        payload: { received: inputValue, validationResult }
      })
    }
  }
}

import type { Entity, TransformedItem } from '~/entity/index.js'
import { Path } from '~/schema/actions/utils/path.js'
import type { Schema, ValidValue } from '~/schema/index.js'
import { isArray } from '~/utils/validation/isArray.js'
import { isObject } from '~/utils/validation/isObject.js'

import {
  isAddition,
  isAppending,
  isDeletion,
  isGetting,
  isPrepending,
  isRemoval,
  isSetting,
  isSubtraction,
  isSum
} from '../symbols/index.js'
import type { UpdateItemInputExtension } from '../types.js'
import type { ExpressionState, UpdateExpression } from './types.js'
import { expressAddUpdate } from './updates/add.js'
import { expressAppendUpdate } from './updates/append.js'
import { expressDeleteUpdate } from './updates/delete.js'
import { expressGetUpdate } from './updates/get.js'
import { expressPrependUpdate } from './updates/prepend.js'
import { expressRemoveUpdate } from './updates/remove.js'
import { expressSetUpdate } from './updates/set.js'
import { expressSubtractUpdate } from './updates/subtract.js'
import { expressSumUpdate } from './updates/sum.js'
import { pathTokens, refOrValueTokens } from './updates/utils.js'

export const expressUpdate = (
  entity: Entity,
  input: TransformedItem<Entity, { mode: 'update'; extension: UpdateItemInputExtension }>
): UpdateExpression => {
  const {
    setExpressions,
    removeExpressions,
    addExpressions,
    deleteExpressions,
    ExpressionAttributeNames,
    ExpressionAttributeValues
  } = expressUpdateRec(input, new Path(), {
    rootSchema: entity.schema,
    setExpressions: [],
    removeExpressions: [],
    addExpressions: [],
    deleteExpressions: [],
    nameCursors: { s: 1, r: 1, a: 1, d: 1 },
    valueCursors: { s: 1, r: 1, a: 1, d: 1 },
    tokens: { s: {}, r: {}, a: {}, d: {} },
    ExpressionAttributeNames: {},
    ExpressionAttributeValues: {}
  })

  const updateExpressions: string[] = []
  if (setExpressions.length > 0) {
    updateExpressions.push(`SET ${setExpressions.join(', ')}`)
  }
  if (removeExpressions.length > 0) {
    updateExpressions.push(`REMOVE ${removeExpressions.join(', ')}`)
  }
  if (addExpressions.length > 0) {
    updateExpressions.push(`ADD ${addExpressions.join(', ')}`)
  }
  if (deleteExpressions.length > 0) {
    updateExpressions.push(`DELETE ${deleteExpressions.join(', ')}`)
  }

  return {
    UpdateExpression: updateExpressions.join(' '),
    ExpressionAttributeNames,
    ExpressionAttributeValues
  }
}

const expressUpdateRec = (
  value: ValidValue<Schema, { mode: 'update'; extension: UpdateItemInputExtension }>,
  path: Path,
  state: ExpressionState
): ExpressionState => {
  if (value === undefined) {
    return state
  }

  if (isSetting(value)) {
    return expressSetUpdate(value, path, state)
  }

  if (isGetting(value)) {
    return expressGetUpdate(value, path, state)
  }

  if (isSum(value)) {
    return expressSumUpdate(value, path, state)
  }

  if (isSubtraction(value)) {
    return expressSubtractUpdate(value, path, state)
  }

  if (isAppending(value)) {
    return expressAppendUpdate(value, path, state)
  }

  if (isPrepending(value)) {
    return expressPrependUpdate(value, path, state)
  }

  if (isRemoval(value)) {
    return expressRemoveUpdate(value, path, state)
  }

  if (isAddition(value)) {
    return expressAddUpdate(value, path, state)
  }

  if (isDeletion(value)) {
    return expressDeleteUpdate(value, path, state)
  }

  if (isObject(value)) {
    for (const [attrName, attrValue] of Object.entries(value)) {
      expressUpdateRec(attrValue, path.append(attrName), state)
    }

    return state
  }

  if (isArray(value)) {
    value.forEach((element, index) => {
      if (element === undefined) {
        return
      }

      expressUpdateRec(element, path.append(index), state)
    })

    return state
  }

  let setExpression = pathTokens(path, 's', state)
  setExpression += ' = '
  setExpression += refOrValueTokens(value, 's', state)
  state.setExpressions.push(setExpression)

  return state
}
