const getDiscriminators = (schema: Schema): Record<string, string> | undefined => {
  switch (schema.type) {
    case 'anyOf':
      return schema[$discriminators]
    case 'map': {
      const discriminators: Record<string, string> = {}

      for (const [attrName, attr] of Object.entries(schema.attributes)) {
